-- EPHEMERAL CI DATABASE ONLY. Contains no real users, transcripts, keys or production connection.
create schema extensions;
create extension pgcrypto with schema extensions;
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,public,extensions to anon,authenticated,service_role;
grant execute on function auth.uid() to authenticated,service_role;
create table profiles(id uuid primary key default gen_random_uuid(),learner_track text);
create table courses(id uuid primary key default gen_random_uuid(),learner_track text,is_active boolean default true);
create table modules(id uuid primary key default gen_random_uuid(),course_id uuid references courses,is_published boolean default true);
create table lessons(id uuid primary key default gen_random_uuid(),module_id uuid references modules,is_published boolean default true);
create table competencies(id uuid primary key default gen_random_uuid(),learner_track text,category text);
create table lesson_competencies(lesson_id uuid,competency_id uuid,weight numeric default 1);
create table user_competency_scores(id uuid primary key default gen_random_uuid(),user_id uuid,competency_id uuid,score numeric default 0,confidence numeric default 0,evidence_count integer default 0,last_assessed_at timestamptz,updated_at timestamptz default now(),unique(user_id,competency_id));
create table user_error_bank(id uuid primary key default gen_random_uuid(),user_id uuid,domain text,pattern text,normalized_pattern text,frequency integer default 1,confidence numeric default 0,last_seen_at timestamptz default now(),next_review_at timestamptz default now(),last_source_type text,last_source_id uuid,examples jsonb default '[]',status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,domain,normalized_pattern));
create table spaced_reviews(id uuid primary key default gen_random_uuid(),user_id uuid,lesson_id uuid,competency_id uuid,review_stage text,due_date date,status text,score numeric,completed_at timestamptz,created_at timestamptz default now());
create table learning_hub_budget_settings(id integer primary key,absolute_total_budget_usd numeric,infrastructure_reserve_usd numeric,ai_hard_cap_usd numeric,professor_cap_usd numeric,premium_audio_cap_usd numeric,updated_at timestamptz default now());
create table professor_budget_settings(feature text primary key,monthly_budget_usd numeric,reservation_usd numeric,premium_reservation_usd numeric,max_session_seconds integer,hard_stop_enabled boolean,updated_at timestamptz default now());
create table professor_budget_reservations(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,feature text default 'professor_livekit',month_start date default date_trunc('month',now())::date,reserved_usd numeric not null check(reserved_usd>0),max_session_seconds integer not null,status text default 'active' check(status in ('active','settled','unresolved','abandoned')),actual_cost_usd numeric not null default 0,settled_at timestamptz,created_at timestamptz default now());
create table ai_tutor_sessions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,lesson_id uuid references lessons,mode text default 'chapter_conversation',status text default 'active',started_at timestamptz default now(),completed_at timestamptz,duration_seconds integer not null default 0,technical_score numeric,english_score numeric,grammar_score numeric,vocabulary_score numeric,fluency_score numeric,pronunciation_score numeric,professional_communication_score numeric,final_feedback jsonb,created_at timestamptz default now(),room_name text,dispatch_id text,quality_tier text,budget_reservation_id uuid references professor_budget_reservations,callback_token_hash text,transcript jsonb not null default '[]',model_usage jsonb not null default '[]',close_reason text,evaluation_model text,evaluation_cost_usd numeric not null default 0);
create table ai_tutor_turns(id uuid primary key default gen_random_uuid(),session_id uuid references ai_tutor_sessions,turn_number integer,speaker text,transcript text,feedback jsonb,created_at timestamptz default now());
create table ai_usage_log(id bigint generated by default as identity primary key,user_id uuid,session_id uuid,feature text,model text,input_tokens bigint default 0,cached_input_tokens bigint default 0,output_tokens bigint default 0,audio_input_tokens bigint default 0,audio_output_tokens bigint default 0,audio_seconds numeric default 0,characters bigint default 0,estimated_cost_usd numeric default 0,request_id text,created_at timestamptz default now());
create unique index ai_usage_log_request_id_uidx on ai_usage_log(request_id) where request_id is not null;
create table professor_validation_flags(user_id uuid primary key,expires_at timestamptz);
alter table ai_tutor_sessions enable row level security;
create policy own_sessions on ai_tutor_sessions to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
grant select,insert,update,delete on ai_tutor_sessions to authenticated;
grant select on profiles,lessons,modules,courses to authenticated;
grant all on all tables in schema public to service_role;
grant usage on all sequences in schema public to service_role;
